"""Eywa types, expression AST, and expression evaluation.

This module owns the typed model surface used by the offline campaign
compiler:

* type objects (``Void``/``Bool``/``Char``/``Int``/``String``/``Enum``/
  ``Array``/``Struct``/``Alias``) with transparent alias resolution;
* the predicate expression AST (``Var``, ``Const``, ``Field``, ``Index``,
  ``Forall``, ``Match``, ``Not``, ``Binop``);
* two evaluators: ``Evaluator`` (a tree walking visitor used for one-shot
  evaluation) and :func:`compile_closure`, which turns an expression tree into
  a zero-argument closure over a mutable environment holder so that the very
  same compiled predicate can be replayed against many symbolic records.

Scoping of ``all`` bindings is lexical: a binding shadows an outer name only
for the duration of its own body and never leaks into enclosing or sibling
predicates.
"""

import uuid
from typing import Any, Callable, Dict, List, Union

import eywa.regex as re

__all__ = [
    'Type', 'Void', 'Bool', 'Char', 'Int', 'String', 'Enum', 'Array', 'Struct',
    'Alias', 'Expr', 'Var', 'Const', 'Not', 'Match', 'Binop', 'Field', 'Index',
    'Forall', 'Evaluator', 'HasMatch', 'Parameter', 'Function', 'FuncModule',
    'NodeVisitor', 'compile_closure', 'canonical_op', 'int_width', 'BINOPS',
]


class NodeVisitor(object):
    """Minimal visitor base class (dispatch on the concrete node type).

    The toolkit deliberately does not import the standard library ``ast``
    module: ``eywa.ast`` would shadow it whenever this directory is first on
    ``sys.path``.
    """

    _dispatch = None

    def visit(self, node):
        cls = type(node)
        dispatch = self._dispatch
        if dispatch is None:
            dispatch = {}
            self._dispatch = dispatch
        method = dispatch.get(cls)
        if method is None:
            method = getattr(self, 'visit_' + cls.__name__, self.generic_visit)
            dispatch[cls] = method
        return method(node)

    def generic_visit(self, node):
        raise Exception(f'no visitor for {type(node).__name__}')


# Canonical predicate operators, plus the legacy symbolic spellings used by the
# Python operator overloads below.
BINOPS = frozenset(('eq', 'ne', 'lt', 'le', 'gt', 'ge', 'add', 'sub', 'and',
                    'or', 'implies'))
_OP_ALIASES = {
    '==': 'eq', '!=': 'ne', '<': 'lt', '<=': 'le', '>': 'gt', '>=': 'ge',
    '+': 'add', '-': 'sub', '&': 'and', '&&': 'and', '|': 'or', '||': 'or',
    '->': 'implies', '=>': 'implies',
}
BOOL_OPS = frozenset(('eq', 'ne', 'lt', 'le', 'gt', 'ge', 'and', 'or',
                      'implies'))


def canonical_op(op: str) -> str:
    """Normalise a binary operator spelling to its canonical name."""
    return _OP_ALIASES.get(op, op)


def int_width(bits: int) -> int:
    """The smallest of 1, 2, 4 or 8 bytes that holds ``bits`` bits."""
    if bits <= 8:
        return 1
    if bits <= 16:
        return 2
    if bits <= 32:
        return 4
    return 8


class Type(object):
    """
    An Eywa type for a parameter to a function.
    """

    __slots__ = ()

    @staticmethod
    def inner(type):
        """
        Look past any type aliases to get the inner type.
        """
        while isinstance(type, Alias):
            type = type.type
        return type


class Void(Type):
    """
    A void type representing no value.
    """

    __slots__ = ('name',)

    def __init__(self, name=None):
        self.name = name


class Bool(Type):
    """
    A boolean type representing true or false.
    """

    __slots__ = ('name',)

    def __init__(self, name=None):
        self.name = name


class Char(Type):
    """
    A character type representing a single character.
    """

    __slots__ = ('name',)

    def __init__(self, name=None):
        self.name = name


class Int(Type):
    """
    An integer type representing an unsigned integer of a given size.
    """

    __slots__ = ('size', 'name')

    def __init__(self, size: int = None, name=None):
        self.size = size
        self.name = name

    @property
    def width(self) -> int:
        return int_width(self.size)


class String(Type):
    """
    A string type representing a string of a given max length.
    """

    __slots__ = ('maxsize', 'char_type', 'name')

    def __init__(self, maxsize: int = 6, name=None):
        if maxsize < 0:
            raise Exception('invalid string type')
        self.maxsize = maxsize
        self.char_type = Char()
        self.name = name


class Enum(Type):
    """
    An enumeration type representing a choice of values.
    """

    __slots__ = ('name', 'values', 'index')

    def __init__(self, name: str, values: List[str]):
        self.name = name
        self.values = list(values)
        self.index = {value: position for position, value in enumerate(self.values)}


class Array(Type):
    """
    An array type representing an array of a given element type and size.
    """

    __slots__ = ('element_type', 'maxsize', 'name')

    def __init__(self, element_type: Type, maxsize: int, name=None):
        self.maxsize = maxsize
        self.element_type = element_type
        self.name = name


class Struct(Type):
    """
    A struct type representing a struct with a given name and fields.
    """

    __slots__ = ('name', 'fields')

    def __init__(self, name: str, fields: Dict[str, Type] = None, **kwargs: Type):
        self.name = name
        if fields is None:
            fields = dict(kwargs)
        elif kwargs:
            fields = dict(fields)
            fields.update(kwargs)
        else:
            # Keep declaration order but own the mapping.
            fields = dict(fields)
        self.fields = fields


class Alias(Type):
    """
    An alias type representing an alias to another type.
    """

    __slots__ = ('name', 'type', 'description')

    def __init__(self, name: str, type: Type, description=None):
        self.name = name
        self.type = type
        self.description = description


class Expr(object):
    """
    A simple expression class.
    """

    __slots__ = ('type',)

    @staticmethod
    def eval(expr, assignment: Dict[str, Any]):
        """
        Evaluate an Eywa expression given an assignment of variables.
        """
        return Evaluator(assignment).visit(expr)

    @staticmethod
    def convert(other):
        """
        Ensures that the given object can be converted to an expression.
        """
        if isinstance(other, Expr):
            return other
        if isinstance(other, bool):
            return Const(Bool(), other)
        if isinstance(other, int):
            return Const(Int(32), other)
        if isinstance(other, str):
            return Const(String(len(other)), other)
        if isinstance(other, Parameter):
            return Var(other.type, other.name)
        raise Exception(f'invalid expression: {other}')

    @staticmethod
    def has_match(type):
        """
        Determines if this expression has a match expression.
        """
        return HasMatch().visit(type)

    def __add__(self, other):
        return Binop(Type.inner(self.type), 'add', self, Expr.convert(other))

    def __sub__(self, other):
        return Binop(Type.inner(self.type), 'sub', self, Expr.convert(other))

    def __and__(self, other):
        return Binop(Bool(), 'and', self, Expr.convert(other))

    def __or__(self, other):
        return Binop(Bool(), 'or', self, Expr.convert(other))

    def __le__(self, other):
        return Binop(Bool(), 'le', self, Expr.convert(other))

    def __lt__(self, other):
        return Binop(Bool(), 'lt', self, Expr.convert(other))

    def __ge__(self, other):
        return Binop(Bool(), 'ge', self, Expr.convert(other))

    def __gt__(self, other):
        return Binop(Bool(), 'gt', self, Expr.convert(other))

    def __eq__(self, other):
        if not isinstance(other, (Expr, Parameter)):
            return NotImplemented
        return Binop(Bool(), 'eq', self, Expr.convert(other))

    def __ne__(self, other):
        if not isinstance(other, (Expr, Parameter)):
            return NotImplemented
        return Binop(Bool(), 'ne', self, Expr.convert(other))

    __hash__ = object.__hash__

    def get_field(self, field: str):
        """
        A helper function to create a field dereference.
        """
        return Field(Type.inner(self.type).fields[field], self, field)

    def get_index(self, index: int):
        """
        A helper function to create an array index dereference.
        """
        return Index(Type.inner(self.type).element_type, self, index)

    def __invert__(self):
        return Not(Bool(), self)

    def matches(self, regex):
        """
        A helper function to create a match constraint.
        """
        return Match(Bool(), self, regex)

    def forall(self, binding, invariant=None):
        """
        A helper function to create an array forall expression.
        """
        if invariant is None:
            # Legacy callable form: expr.forall(lambda var: ...)
            return Forall(Bool(), self, binding)
        return Forall(Bool(), self, invariant, binding)

    def implies(self, other):
        """
        A helper function to create an implies expression.
        """
        return Binop(Bool(), 'implies', self, Expr.convert(other))


class Var(Expr):
    """
    A variable expression.
    """

    __slots__ = ('type', 'parameter_name')

    def __init__(self, type, parameter_name):
        self.type = type
        self.parameter_name = parameter_name


class Const(Expr):
    """
    A constant expression.
    """

    __slots__ = ('type', 'constant')

    def __init__(self, type, constant):
        inner = Type.inner(type)
        if isinstance(inner, String) and not isinstance(constant, str):
            raise Exception('Constant expression type mismatch')
        if isinstance(inner, Char) and not isinstance(constant, str):
            raise Exception('Constant expression type mismatch')
        if isinstance(inner, Int) and not isinstance(constant, int):
            raise Exception('Constant expression type mismatch')
        if isinstance(inner, Bool) and not isinstance(constant, bool):
            raise Exception('Constant expression type mismatch')
        self.type = type
        self.constant = constant


class Not(Expr):
    """
    A not expression.
    """

    __slots__ = ('type', 'expr')

    def __init__(self, type, expr: Expr):
        if not isinstance(type, Bool):
            raise Exception('Not expression expected bool return type')
        self.type = type
        self.expr = expr


class Match(Expr):
    """
    A expr for a regular expression match.
    """

    __slots__ = ('type', 'expr', 'regex')

    def __init__(self, type, expr: Expr, regex):
        if not isinstance(type, Bool):
            raise Exception('Match expression expected bool return type')
        if not isinstance(Type.inner(expr.type), String):
            raise Exception('Match expression expected string type')
        if isinstance(regex, str):
            regex = re.compile_pattern(regex)
        self.type = type
        self.expr = expr
        self.regex = regex


class Binop(Expr):
    """
    A binary operation expression.
    """

    __slots__ = ('type', 'op', 'left', 'right', 'modulus')

    def __init__(self, type, op: str, left: Expr, right: Expr):
        self.type = type
        self.op = canonical_op(op)
        self.left = left
        self.right = right
        self.modulus = None
        if self.op in ('add', 'sub'):
            inner = Type.inner(type)
            if isinstance(inner, Int) and inner.size:
                self.modulus = (1 << inner.size) - 1
            else:
                operand = Type.inner(left.type)
                if isinstance(operand, Int) and operand.size:
                    self.modulus = (1 << operand.size) - 1


class Field(Expr):
    """
    A field dereference expression.
    """

    __slots__ = ('type', 'expr', 'field')

    def __init__(self, type, expr: Expr, field: str):
        inner = Type.inner(expr.type)
        if not isinstance(inner, Struct):
            raise Exception('Field expression expected struct type')
        if field not in inner.fields:
            raise Exception('Field expression expected a declared field')
        self.type = type
        self.expr = expr
        self.field = field


class Index(Expr):
    """
    A fixed array index expression.
    """

    __slots__ = ('type', 'expr', 'index')

    def __init__(self, type, expr: Expr, index: int):
        inner = Type.inner(expr.type)
        if not isinstance(inner, Array):
            raise Exception('Index expression expected array type')
        if not isinstance(index, int) or isinstance(index, bool):
            raise Exception('Index expression expected an integer index')
        if index < 0 or index >= inner.maxsize:
            raise Exception('Index expression expected a valid index')
        self.type = type
        self.expr = expr
        self.index = index


class Forall(Expr):
    """
    An array forall expression.

    Two shapes are supported: a named binding with an already built body
    (``Forall(Bool(), array, body, binding)``), which is what the campaign
    predicate language produces, and the legacy callable invariant form
    (``Forall(Bool(), array, lambda var: ...)``).
    """

    __slots__ = ('type', 'array_expr', 'binding', 'body', 'invariant')

    def __init__(self, type, expr, body, binding: str = None):
        if not isinstance(type, Bool):
            raise Exception('forall expression expected bool return type')
        array_expr = Expr.convert(expr)
        if not isinstance(Type.inner(array_expr.type), Array):
            raise Exception('forall expression expected array type')
        self.type = type
        self.array_expr = array_expr
        if binding is None and not isinstance(body, Expr):
            # Legacy form: the invariant is a callable taking a fresh Var.
            self.binding = None
            self.body = None
            self.invariant = body
        else:
            if binding is None:
                binding = '_' + uuid.uuid4().hex
            self.binding = binding
            self.body = body
            self.invariant = None

    def element_type(self):
        return Type.inner(self.array_expr.type).element_type

    def build_body(self):
        """Materialise the body expression for the legacy callable form."""
        if self.body is not None:
            return self.body, self.binding
        name = '_' + uuid.uuid4().hex
        return self.invariant(Var(self.element_type(), name)), name


class Evaluator(NodeVisitor):
    """
    A class that evaluates an Eywa Expression and returns a value.

    The assignment is a stack of lexical scopes; the innermost binding of a
    name wins, and popping a scope restores any shadowed outer value.
    """

    def __init__(self, assignment):
        if isinstance(assignment, dict):
            self.scopes = [assignment]
        else:
            self.scopes = list(assignment)

    def lookup(self, name):
        for scope in reversed(self.scopes):
            if name in scope:
                return scope[name]
        raise Exception(f'unbound variable: {name}')

    def visit_Var(self, node):
        return self.lookup(node.parameter_name)

    def visit_Const(self, node):
        return node.constant

    def visit_Not(self, node):
        return not self.visit(node.expr)

    def visit_Match(self, node):
        return re.ismatch(node.regex, self.visit(node.expr))

    def visit_Field(self, node):
        return self.visit(node.expr)[node.field]

    def visit_Index(self, node):
        return self.visit(node.expr)[node.index]

    def visit_Forall(self, node):
        body, binding = node.build_body()
        array = self.visit(node.array_expr)
        scope = {}
        self.scopes.append(scope)
        try:
            for element in array:
                scope[binding] = element
                if not self.visit(body):
                    return False
            return True
        finally:
            self.scopes.pop()

    def visit_Binop(self, node):
        op = node.op
        left = self.visit(node.left)
        if op == 'and':
            return bool(left) and bool(self.visit(node.right))
        if op == 'or':
            return bool(left) or bool(self.visit(node.right))
        if op == 'implies':
            return (not bool(left)) or bool(self.visit(node.right))
        right = self.visit(node.right)
        if op == 'eq':
            return left == right
        if op == 'ne':
            return left != right
        if op == 'lt':
            return left < right
        if op == 'le':
            return left <= right
        if op == 'gt':
            return left > right
        if op == 'ge':
            return left >= right
        if op == 'add':
            modulus = node.modulus
            return (left + right) if modulus is None else (left + right) & modulus
        if op == 'sub':
            modulus = node.modulus
            return (left - right) if modulus is None else (left - right) & modulus
        raise Exception(f'Unknown binary operator: {node.op}')


class HasMatch(NodeVisitor):
    """
    A class that checks if an Eywa Expression has a match expression.
    """

    def visit_Var(self, node): return False
    def visit_Const(self, node): return False
    def visit_Match(self, node): return True
    def visit_Not(self, node): return self.visit(node.expr)
    def visit_Field(self, node): return self.visit(node.expr)
    def visit_Index(self, node): return self.visit(node.expr)

    def visit_Binop(self, node): return self.visit(
        node.left) or self.visit(node.right)

    def visit_Forall(self, node):
        body, binding = node.build_body()
        return self.visit(node.array_expr) or self.visit(body)


_MISSING = object()


def compile_closure(node, holder):
    """Compile an expression tree into a zero-argument closure.

    ``holder`` is a single element list holding the environment dictionary to
    evaluate against; swapping ``holder[0]`` retargets the compiled predicate,
    so a campaign predicate is compiled exactly once and replayed for every
    record and every composed filter application.
    """
    cls = type(node)
    if cls is Var:
        name = node.parameter_name

        def read_var():
            return holder[0][name]
        return read_var
    if cls is Const:
        value = node.constant

        def read_const():
            return value
        return read_const
    if cls is Field:
        operand = compile_closure(node.expr, holder)
        field = node.field

        def read_field():
            return operand()[field]
        return read_field
    if cls is Index:
        operand = compile_closure(node.expr, holder)
        index = node.index

        def read_index():
            return operand()[index]
        return read_index
    if cls is Not:
        operand = compile_closure(node.expr, holder)

        def read_not():
            return not operand()
        return read_not
    if cls is Match:
        operand = compile_closure(node.expr, holder)
        matcher = node.regex
        if isinstance(matcher, str):
            matcher = re.compile_pattern(matcher)

        def read_match():
            return matcher.matches(operand())
        return read_match
    if cls is Forall:
        array = compile_closure(node.array_expr, holder)
        body, binding = node.build_body()
        body_closure = compile_closure(body, holder)

        def read_forall():
            environment = holder[0]
            shadowed = environment.get(binding, _MISSING)
            try:
                for element in array():
                    environment[binding] = element
                    if not body_closure():
                        return False
                return True
            finally:
                if shadowed is _MISSING:
                    environment.pop(binding, None)
                else:
                    environment[binding] = shadowed
        return read_forall
    if cls is Binop:
        op = node.op
        left = compile_closure(node.left, holder)
        if op == 'and':
            right = compile_closure(node.right, holder)

            def read_and():
                return left() and right()
            return read_and
        if op == 'or':
            right = compile_closure(node.right, holder)

            def read_or():
                return left() or right()
            return read_or
        if op == 'implies':
            right = compile_closure(node.right, holder)

            def read_implies():
                return (not left()) or right()
            return read_implies
        right = compile_closure(node.right, holder)
        if op == 'eq':
            def read_eq():
                return left() == right()
            return read_eq
        if op == 'ne':
            def read_ne():
                return left() != right()
            return read_ne
        if op == 'lt':
            def read_lt():
                return left() < right()
            return read_lt
        if op == 'le':
            def read_le():
                return left() <= right()
            return read_le
        if op == 'gt':
            def read_gt():
                return left() > right()
            return read_gt
        if op == 'ge':
            def read_ge():
                return left() >= right()
            return read_ge
        modulus = node.modulus
        if op == 'add':
            if modulus is None:
                def read_add():
                    return left() + right()
            else:
                def read_add():
                    return (left() + right()) & modulus
            return read_add
        if op == 'sub':
            if modulus is None:
                def read_sub():
                    return left() - right()
            else:
                def read_sub():
                    return (left() - right()) & modulus
            return read_sub
        raise Exception(f'Unknown binary operator: {op}')
    raise Exception(f'cannot compile expression node {cls.__name__}')


class Predicate(object):
    """A compiled predicate: an expression plus its environment holder."""

    __slots__ = ('expr', 'holder', 'closure')

    def __init__(self, expr, environment=None):
        self.expr = expr
        self.holder = [environment if environment is not None else {}]
        self.closure = None if expr is None else compile_closure(expr, self.holder)

    def evaluate(self, environment=None):
        if self.closure is None:
            return True
        if environment is not None:
            self.holder[0] = environment
        return bool(self.closure())


class Parameter:
    """
    An Eywa parameter to a function.
    """

    __slots__ = ('name', 'type', 'description')

    def __init__(self, name: str, type: Type, description: Union[str, None] = None):
        self.name = name
        self.type = type
        self.description = description

    def __add__(self, other):
        return Binop(Type.inner(self.type), 'add', Expr.convert(self), Expr.convert(other))

    def __sub__(self, other):
        return Binop(Type.inner(self.type), 'sub', Expr.convert(self), Expr.convert(other))

    def __and__(self, other):
        return Binop(Bool(), 'and', Expr.convert(self), Expr.convert(other))

    def __or__(self, other):
        return Binop(Bool(), 'or', Expr.convert(self), Expr.convert(other))

    def __le__(self, other):
        return Binop(Bool(), 'le', Expr.convert(self), Expr.convert(other))

    def __lt__(self, other):
        return Binop(Bool(), 'lt', Expr.convert(self), Expr.convert(other))

    def __ge__(self, other):
        return Binop(Bool(), 'ge', Expr.convert(self), Expr.convert(other))

    def __gt__(self, other):
        return Binop(Bool(), 'gt', Expr.convert(self), Expr.convert(other))

    def __eq__(self, other):
        if not isinstance(other, (Expr, Parameter)):
            return NotImplemented
        return Binop(Bool(), 'eq', Expr.convert(self), Expr.convert(other))

    def __ne__(self, other):
        if not isinstance(other, (Expr, Parameter)):
            return NotImplemented
        return Binop(Bool(), 'ne', Expr.convert(self), Expr.convert(other))

    __hash__ = object.__hash__

    def __invert__(self):
        return Not(Bool(), Expr.convert(self))

    def matches(self, regex) -> Expr:
        """
        A helper function to create a match constraint.
        """
        return Match(Bool(), Expr.convert(self), regex)

    def get_field(self, field: str) -> Expr:
        """
        A helper function to create a field dereference.
        """
        return Field(Type.inner(self.type).fields[field], Expr.convert(self), field)

    def get_index(self, index: int) -> Expr:
        """
        A helper function to create an array index dereference.
        """
        return Index(Type.inner(self.type).element_type, Expr.convert(self), index)

    def forall(self, binding, invariant=None) -> Expr:
        """
        A helper function to create an array forall expression.
        """
        if invariant is None:
            return Forall(Bool(), Expr.convert(self), binding)
        return Forall(Bool(), Expr.convert(self), invariant, binding)

    def implies(self, other) -> Expr:
        """
        A helper function to create an implies expression.
        """
        return Binop(Bool(), 'implies', Expr.convert(self), Expr.convert(other))


class Function:
    """
    An Eywa function that represents a model.
    """

    __slots__ = ('name', 'description', 'inputs', 'result', 'precondition')

    def __init__(self, name: str, description: str, inputs: List[Parameter],
                 precondition: Union[Expr, None] = None):
        unique_names = set(map(lambda x: x.name, inputs))
        if len(unique_names) != len(inputs):
            raise Exception('duplicate parameter names')
        self.name = name
        self.description = description
        if inputs and isinstance(inputs[-1].type, Void):
            self.inputs = list(inputs)
            self.result = None
        else:
            self.inputs = inputs[:-1]
            self.result = inputs[-1]
        self.precondition = precondition


class FuncModule(Function):
    """
    An Eywa function module used for composition
    """

    __slots__ = ()

    def __init__(self, name: str, description: str, inputs: List[Parameter]):
        Function.__init__(self, name, description, inputs, None)
